get_product_listing.code:
use WebCommander\Sdk\Resources\Settings\ProductListing\ProductListing;

$response = ProductListing::getProductListing($client);

$settings = $response->map['product_listing'];
echo $settings['load']['pagination']['per_page'], ' products per page', PHP_EOL;
echo 'sorting: ', $settings['sorting']['enabled'] ? 'on' : 'off', PHP_EOL;

patch_product_listing.code:
use WebCommander\Sdk\Resources\Settings\ProductListing\ProductListing;

$response = ProductListing::patchProductListing($client, [
    'product_listing' => [
        'sorting' => ['enabled' => true, 'sort_by' => 'price_asc'],
        'load' => ['pagination' => ['per_page' => 24]],
    ],
]);

$settings = $response->map['product_listing'];
echo $settings['sorting']['sort_by'], PHP_EOL;
echo $settings['load']['pagination']['per_page'], ' products per page', PHP_EOL;
